\documentclass[border=5pt]{standalone}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\usepackage{xeCJK}
\setCJKmainfont{SimSun}

\begin{document}
\begin{tikzpicture}
\begin{axis}[
    width=12cm,
    height=8cm,
    ybar,
    bar width=15pt,
    ymajorgrids=true,
    ylabel={报名人数},
    xlabel={年份},
    symbolic x coords={2021,2022,2023,2024,2025,2026},
    xtick=data,
    nodes near coords,
    nodes near coords align={vertical},
    every node near coord/.append style={
        font=\small,
        yshift=5pt,
        rotate=90
    },
    enlarge x limits=0.15,
    ymin=0,
    ymax=500,
    title={2011-2026年考研报名人数变化趋势},
    title style={yshift=10pt, font=\large\bfseries},
    tick label style={font=\small},
    label style={font=\small},
    legend style={font=\small}
]

% 添加数据柱
\addplot[fill=blue!50] coordinates {
    (2021, 377)
    (2022, 457)
    (2023, 474)
    (2024, 438)
    (2025, 388)
    (2026, 343)
};

% 添加趋势线（可选）
\addplot[red, thick, dashed, mark=none] coordinates {
    (2021, 377)
    (2022, 457)
    (2023, 474)
    (2024, 438)
    (2025, 388)
    (2026, 343)
};

\legend{报名人数, 趋势线}

\end{axis}
\end{tikzpicture}
\end{document}
